<?php

namespace App\Entity;

use App\Repository\BehavioralInterpretationRepository;
use Doctrine\ORM\Mapping as ORM;
use Symfony\Bridge\Doctrine\Types\UuidType;
use Symfony\Component\Serializer\Attribute\Ignore;
use Symfony\Component\Uid\Uuid;

/**
 * Stores the AI-generated behavioral interpretation for a meeting.
 * One interpretation per meeting (OneToOne), generated by qwen3:4b via Ollama.
 *
 * Structure
 * ---------
 * meeting_dynamics : string — group-level behavioral narrative
 * speakers         : array  — per-speaker profiles (role, analysis, strengths, etc.)
 * model            : string — LLM model used (e.g. "qwen3:4b")
 * language         : string — language of the generated text (e.g. "fr")
 * generated_at     : DateTimeImmutable — when the interpretation was produced
 */
#[ORM\Entity(repositoryClass: BehavioralInterpretationRepository::class)]
#[ORM\Table(name: 'behavioral_interpretation')]
class BehavioralInterpretation
{
    #[ORM\Id]
    #[ORM\Column(type: UuidType::NAME, unique: true)]
    #[ORM\GeneratedValue(strategy: 'CUSTOM')]
    #[ORM\CustomIdGenerator(class: 'doctrine.uuid_generator')]
    private ?Uuid $id = null;

    #[ORM\OneToOne(targetEntity: Meeting::class, inversedBy: 'behavioralInterpretation')]
    #[ORM\JoinColumn(nullable: false, onDelete: 'CASCADE')]
    #[Ignore]
    private ?Meeting $meeting = null;

    /** Global group dynamics narrative paragraph. */
    #[ORM\Column(type: 'text')]
    private string $meetingDynamics = '';

    /**
     * Per-speaker profiles.
     * Keys = speaker name, values = {role_label, profile_summary,
     * psychological_analysis, vocal_signature, strengths,
     * areas_to_watch, style_quote, style_description, recommendation}
     */
    #[ORM\Column(type: 'json')]
    private array $speakers = [];

    /** LLM model that generated this interpretation. */
    #[ORM\Column(length: 100)]
    private string $model = 'qwen3:4b';

    /** Language of the generated text (BCP-47 code). */
    #[ORM\Column(length: 10)]
    private string $language = 'fr';

    /** When the AI finished generating the interpretation. */
    #[ORM\Column]
    private \DateTimeImmutable $generatedAt;

    #[ORM\Column]
    private \DateTimeImmutable $createdAt;

    #[ORM\Column]
    private \DateTimeImmutable $updatedAt;

    public function __construct()
    {
        $this->generatedAt = new \DateTimeImmutable();
        $this->createdAt   = new \DateTimeImmutable();
        $this->updatedAt   = new \DateTimeImmutable();
    }

    // ── Getters & Setters ──────────────────────────────────────────────────────

    public function getId(): ?Uuid
    {
        return $this->id;
    }

    public function getMeeting(): ?Meeting
    {
        return $this->meeting;
    }

    public function setMeeting(?Meeting $meeting): static
    {
        $this->meeting = $meeting;
        return $this;
    }

    public function getMeetingDynamics(): string
    {
        return $this->meetingDynamics;
    }

    public function setMeetingDynamics(string $meetingDynamics): static
    {
        $this->meetingDynamics = $meetingDynamics;
        return $this;
    }

    public function getSpeakers(): array
    {
        return $this->speakers;
    }

    public function setSpeakers(array $speakers): static
    {
        $this->speakers = $speakers;
        return $this;
    }

    public function getModel(): string
    {
        return $this->model;
    }

    public function setModel(string $model): static
    {
        $this->model = $model;
        return $this;
    }

    public function getLanguage(): string
    {
        return $this->language;
    }

    public function setLanguage(string $language): static
    {
        $this->language = $language;
        return $this;
    }

    public function getGeneratedAt(): \DateTimeImmutable
    {
        return $this->generatedAt;
    }

    public function setGeneratedAt(\DateTimeImmutable $generatedAt): static
    {
        $this->generatedAt = $generatedAt;
        return $this;
    }

    public function getCreatedAt(): \DateTimeImmutable
    {
        return $this->createdAt;
    }

    public function getUpdatedAt(): \DateTimeImmutable
    {
        return $this->updatedAt;
    }

    public function setUpdatedAt(\DateTimeImmutable $updatedAt): static
    {
        $this->updatedAt = $updatedAt;
        return $this;
    }

    /**
     * Returns the full interpretation as a plain array
     * (same shape expected by the frontend / AnalyticsController).
     */
    public function toArray(): array
    {
        return [
            'meeting_dynamics' => $this->meetingDynamics,
            'speakers'         => $this->speakers,
        ];
    }
}
